// Synthetic demonstration fixtures only; no real customer, tax, banking or contact records.
const $=(s,r)=>r?[...r.querySelectorAll(s)]:document.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const STORE='ati-ecp-demo-v4';
const initial={application:{step:0,status:'Draft',submittedAt:null,entered:false},vendor:{status:'Pending review',activation:72},catalog:{total:24,ready:21,issues:3,published:0},inventory:{sync:'Healthy',units:184},orders:{'ECP-785204':'Ready to pack','ECP-785198':'New'},returns:{'RTN-10428':'QC pending'},settlement:{status:'Preview'},events:[]};
let state=load();
function load(){try{return {...structuredClone(initial),...JSON.parse(localStorage.getItem(STORE)||'{}')}}catch{return structuredClone(initial)}}
function save(event){if(event){state.events.unshift({event,at:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})});state.events=state.events.slice(0,20)}localStorage.setItem(STORE,JSON.stringify(state));}
function reset(){localStorage.removeItem(STORE);state=structuredClone(initial);toast('Demo reset to its starting state');setTimeout(()=>location.reload(),650)}
function toast(message){const el=$('#toast');if(!el)return;el.textContent=message;el.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>el.classList.remove('show'),2500)}
function pill(text,type=''){return `<span class="pill ${type}"><i class="dot"></i>${text}</span>`}
function header(title,description,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${description}</p></div><div class="page-actions">${actions}</div></div>`}
function modal(content){$('#modal-root').innerHTML=`<div class="modal-backdrop" data-close-modal><section class="modal" onclick="event.stopPropagation()"><button class="close-x" data-close-modal>×</button>${content}</section></div>`;$$('[data-close-modal]').forEach(x=>x.onclick=()=>$('#modal-root').innerHTML='')}
function wireCommon(root=document){$$('[data-toast]',root).forEach(x=>x.onclick=()=>toast(x.dataset.toast));$$('[data-reset]',root).forEach(x=>x.onclick=reset)}

// ----- Launchpad
if(document.body.dataset.app==='launch'){$('#reset-demo').onclick=reset}

// ----- Application
const steps=[
 ['Business','Company and contacts'],['Authorization','Brands and markets'],['Compliance','Documents and tax'],['Commercials','Terms and settlement'],['Catalogue','Products and assets'],['Inventory','Locations and sync'],['Operations','Fulfilment and returns'],['Review','Submit for approval']
];
const foot=(last=false)=>`<div class="form-footer"><small>Progress is saved automatically</small><div><button class="btn" data-prev>Back</button> <button class="btn wine" data-next>${last?'Submit application':'Save & continue →'}</button></div></div>`;
const field=(label,value,type='text',full='')=>`<label class="field ${full}">${label}<input type="${type}" value="${value}"></label>`;
const appPages=[
 ()=>`<span class="eyebrow">Step 1 of 8 · Business</span><h2>Tell us about your company</h2><p class="intro">This creates your provisional partner profile. ATI’s existing ERP remains the vendor master after approval.</p><div class="form-section"><h3>Legal entity</h3><div class="field-grid">${field('Legal company name','Maison Elan Trading LLC')}${field('Trading name','Maison Élan')}${field('Country of incorporation','United Arab Emirates')}${field('Trade licence number','DEMO-LICENCE-001')}${field('Business category','Fashion & accessories')}${field('Company website','www.maisonelan.example')}</div></div><div class="form-section"><h3>Primary contact</h3><div class="field-grid">${field('Full name','Demo Partner Contact')}${field('Job title','E-commerce Director')}${field('Work email','leila@maisonelan.example','email')}${field('Mobile number','DEMO-PHONE-NOT-VALID')}</div></div>${foot()}`,
 ()=>`<span class="eyebrow">Step 2 of 8 · Authorization</span><h2>Which brands will you represent?</h2><p class="intro">ATI uses a brand registry to prevent unauthorized sellers and control where each brand may trade.</p><div class="form-section"><h3>Brand ownership</h3><div class="choice-grid"><button class="choice selected"><b>Brand owner</b><small>We own the trademark and distribution rights.</small></button><button class="choice"><b>Authorized distributor</b><small>We hold a valid distribution agreement.</small></button><button class="choice"><b>Marketplace seller</b><small>We resell products from approved brands.</small></button></div></div><div class="form-section"><h3>Brand and markets</h3><div class="field-grid">${field('Brand name','Maison Élan')}${field('Trademark registration','DEMO-TRADEMARK-001')}${field('Requested categories','Women / Contemporary')}${field('Authorized market','United Arab Emirates')}<label class="field full">Authorization notes<textarea>Exclusive UAE distribution rights held by Maison Elan Trading LLC.</textarea></label></div></div><div class="upload-row"><span><b>Brand authorization letter</b><small>PDF · Signed · Expires 31 Dec 2028</small></span>${pill('Uploaded')}</div>${foot()}`,
 ()=>`<span class="eyebrow">Step 3 of 8 · Compliance</span><h2>Complete compliance checks</h2><p class="intro">Documents are reviewed by ATI and retained with version history, expiry reminders and a full audit trail.</p><div class="form-section"><h3>Required documents</h3><div class="upload-row"><span><b>UAE trade licence</b><small>PDF or JPG · Max 10 MB</small></span><button class="btn small" data-upload>Replace</button></div><div class="upload-row"><span><b>VAT registration certificate</b><small>TRN DEMO-TRN-NOT-VALID</small></span>${pill('Verified')}</div><div class="upload-row"><span><b>Bank confirmation letter</b><small>Needed for finance setup</small></span><button class="btn small" data-upload>Upload</button></div><div class="upload-row"><span><b>Product liability insurance</b><small>Expires 18 March 2027</small></span>${pill('Uploaded')}</div></div><div class="form-section"><div class="field-grid">${field('VAT registration number','DEMO-TRN-NOT-VALID')}${field('Registered address','Dubai Design District, Dubai')}</div></div>${foot()}`,
 ()=>`<span class="eyebrow">Step 4 of 8 · Commercials</span><h2>Review your commercial profile</h2><p class="intro">ATI configures approved rates and payout terms. Disbursement remains in ATI finance; the platform produces transparent transaction-level statements.</p><div class="notice amber"><strong>Indicative until countersigned</strong>Final terms become active only after ATI commercial approval.</div><div class="form-section"><div class="field-grid"><label class="field">Settlement currency<select><option>AED — UAE Dirham</option></select></label><label class="field">Settlement cadence<select><option>Twice monthly</option><option>Monthly</option></select></label><label class="field">Default commission<input value="28%"></label><label class="field">Settlement bank account<input value="DEMO ACCOUNT · No banking details"></label><label class="field full">Promotion participation<select><option>Opt in per campaign</option><option>Always opt in</option></select></label></div></div><div class="review-block" style="margin-top:16px"><b>What statements include</b><p>Gross sales, commission, VAT, shipping, brand-funded promotion contribution, returns, chargebacks, adjustments and net payable.</p></div>${foot()}`,
 ()=>`<span class="eyebrow">Step 5 of 8 · Catalogue</span><h2>Choose how products will arrive</h2><p class="intro">Fynd AI PIM maps your source data to ATI taxonomy, checks duplicates and image quality, creates Arabic content, and routes exceptions for review.</p><div class="choice-grid"><button class="choice selected"><b>Excel / CSV</b><small>Start with ATI’s validated template.</small></button><button class="choice"><b>Direct API</b><small>Near-real-time catalogue sync.</small></button><button class="choice"><b>SFTP / connector</b><small>Scheduled feed or Shopify-style connector.</small></button></div><div class="form-section"><h3>Sample catalogue</h3><div class="upload-row"><span><b>maison-elan-uae-24-products.xlsx</b><small>24 products · 68 variants · Uploaded today</small></span>${pill('21 ready')}</div><div class="grid-3"><div class="review-block"><b>Taxonomy mapped</b><p>24 / 24 products</p></div><div class="review-block"><b>Duplicates found</b><p>1 possible match</p></div><div class="review-block"><b>Content issues</b><p>2 Arabic fields</p></div></div></div><div class="form-section"><h3>Image sources</h3><div class="field-grid"><label class="field">Primary source<select><option>Image URLs in catalogue</option><option>ZIP upload</option><option>Vendor DAM</option></select></label><label class="field">Missing imagery<select><option>Request AI lifestyle/on-model generation</option><option>Hold product</option></select></label></div></div>${foot()}`,
 ()=>`<span class="eyebrow">Step 6 of 8 · Inventory</span><h2>Connect inventory and locations</h2><p class="intro">Availability is maintained by SKU and location, with safety stock and sellable thresholds protecting the storefront from overselling.</p><div class="form-section"><h3>Source locations</h3><div class="upload-row"><span><b>Dubai Design District warehouse</b><small>DXB-D3-01 · 184 sellable units</small></span>${pill('Connected')}</div><div class="upload-row"><span><b>Dubai Mall boutique</b><small>DXB-DM-02 · BOPIS eligible</small></span>${pill('Connected')}</div></div><div class="form-section"><div class="field-grid"><label class="field">Inventory method<select><option>Near-real-time API</option><option>SFTP file</option><option>Portal update</option></select></label><label class="field">Default safety buffer<select><option>2 units per SKU-location</option><option>5 units per SKU-location</option></select></label><label class="field">Zero-stock handling<select><option>Hide from sale immediately</option></select></label><label class="field">Reconciliation frequency<select><option>Every 15 minutes</option></select></label></div></div>${foot()}`,
 ()=>`<span class="eyebrow">Step 7 of 8 · Operations</span><h2>Confirm fulfilment readiness</h2><p class="intro">Customers see Bloomingdale’s throughout. Vendor ownership is abstracted while each fulfilment leg remains independently managed and measured.</p><div class="form-section"><h3>Fulfilment model</h3><div class="choice-grid"><button class="choice selected"><b>Brand fulfilled</b><small>Pick, pack and hand over from your location.</small></button><button class="choice"><b>ATI warehouse</b><small>Stock held and fulfilled by ATI.</small></button><button class="choice"><b>Hybrid</b><small>Route by SKU and availability.</small></button></div></div><div class="form-section"><div class="field-grid"><label class="field">Order confirmation SLA<select><option>30 minutes</option></select></label><label class="field">Dispatch SLA<select><option>Same business day</option></select></label><label class="field">Return window<select><option>30 days + 7 operational days</option></select></label><label class="field">Return destination<select><option>ATI Returns Hub</option></select></label></div></div><div class="upload-row"><span><b>ATI-branded pack documentation</b><small>Training guide acknowledged</small></span>${pill('Ready')}</div><div class="upload-row"><span><b>Test order</b><small>Run after catalogue publication</small></span>${pill('Pending','amber')}</div>${foot()}`,
 ()=>`<span class="eyebrow">Step 8 of 8 · Review</span><h2>Ready for ATI review</h2><p class="intro">Confirm your application. ATI may approve it, reject it with a reason, or request more information.</p><div class="review-grid"><div class="review-block"><b>Business & contact</b><p>Maison Elan Trading LLC<br>Demo Partner Contact · E-commerce Director</p></div><div class="review-block"><b>Brand authorization</b><p>Maison Élan · UAE<br>Brand owner</p></div><div class="review-block"><b>Compliance</b><p>3 verified · 1 uploaded<br>TRN DEMO-TRN-NOT-VALID</p></div><div class="review-block"><b>Commercial terms</b><p>AED · Twice monthly<br>28% indicative commission</p></div><div class="review-block"><b>Catalogue</b><p>24 products · 21 ready<br>3 issues identified</p></div><div class="review-block"><b>Operations</b><p>Brand fulfilled · Same-day dispatch<br>ATI returns hub</p></div></div><label style="display:flex;gap:9px;margin-top:20px;font-size:11px;line-height:1.5"><input type="checkbox" checked>I am authorized to submit this application and confirm that the information is accurate.</label>${foot(true)}`
];
function renderApply(){const s=state.application.step;$('#apply-steps').innerHTML=steps.map((x,i)=>`<div class="step-item ${i===s?'active':''} ${i<s?'done':''}"><span class="step-number">${i<s?'✓':i+1}</span><span><b>${x[0]}</b><small>${x[1]}</small></span></div>`).join('');if(state.application.status==='Submitted'||state.application.status==='Approved'){$('#apply-content').innerHTML=`<div class="success"><div class="success-mark">✓</div><span class="eyebrow">Application ${state.application.status}</span><h2>${state.application.status==='Approved'?'Welcome to the network.':'Thank you, Maison Élan.'}</h2><p class="intro" style="margin:auto">${state.application.status==='Approved'?'ATI has approved your brand. Continue in the Partner Workspace to complete catalogue and test-order activation.':'ATI has received your application. You may continue preparing product content while the review is completed.'}</p><div class="success-ref"><div><small>REFERENCE</small><b>ECP-UAE-2027-0048</b></div><div><small>STATUS</small><b>${state.application.status}</b></div><div><small>NEXT STEP</small><b>${state.application.status==='Approved'?'Activation':'ATI review'}</b></div></div><div class="success-actions"><a class="btn" href="/">Demo home</a><a class="btn wine" href="/partner/">Open partner workspace →</a></div></div>`;return}$('#apply-content').innerHTML=appPages[s]();$$('.choice').forEach(c=>c.onclick=()=>{c.parentElement.querySelectorAll('.choice').forEach(x=>x.classList.remove('selected'));c.classList.add('selected')});$$('[data-upload]').forEach(x=>x.onclick=()=>toast('Demo upload completed'));const prev=$('[data-prev]');if(prev)prev.onclick=()=>{state.application.step=Math.max(0,s-1);save();renderApply()};const next=$('[data-next]');if(next)next.onclick=()=>{if(s===7){state.application.status='Submitted';state.vendor.status='Pending review';state.application.submittedAt=new Date().toISOString();save('Maison Élan submitted application ECP-UAE-2027-0048');toast('Application submitted to ATI');}else{state.application.step=s+1;save();}renderApply();scrollTo({top:0,behavior:'smooth'})}}
const renderApplicationSteps=renderApply;
renderApply=function(){
  const shell=$('#apply-shell');
  if(!state.application.entered){
    shell.classList.add('auth-mode');
    $('#apply-content').innerHTML=`<section class="partner-signin"><span class="signin-kicker">Bloomingdale’s UAE Partner Network</span><h2>Sign in to your invitation</h2><p>Use the email address that received your Bloomingdale’s partner invitation. This secure workspace is separate from a customer account.</p><div class="invite-summary"><span>INVITED BRAND<b>Maison Élan</b></span><span>MARKET<b>United Arab Emirates</b></span><span>REFERENCE<b>ECP-UAE-2027-0048</b></span></div><label>Email<input type="email" value="leila@maisonelan.example" aria-label="Email"></label><label><span class="password-line"><span>Password</span><button type="button" data-toast="Password reset instructions sent">Forgot password</button></span><input type="password" value="demopassword" aria-label="Password"></label><button class="signin-primary" data-enter-application>Continue</button><div class="signin-help">Don’t have an invitation? <button data-toast="Invitation request form opened">Request access</button></div></section>`;
    $('[data-enter-application]').onclick=()=>{state.application.entered=true;save('Maison Élan opened its partner application');renderApply();scrollTo({top:0,behavior:'smooth'})};
    wireCommon($('#apply-content'));
    return;
  }
  shell.classList.remove('auth-mode');
  renderApplicationSteps();
  wireCommon($('#apply-content'));
};
if(document.body.dataset.app==='apply')renderApply();

