function orderModal(id){const status=state.orders[id];modal(`<span class="eyebrow">Assigned fulfilment leg</span><h2>${id}</h2><p class="muted">Bloomingdale’s UAE · 1 item · AED ${id==='ECP-785198'?'2,250':'1,850'}</p><div class="order-workflow"><div class="done"><i></i>Received</div><div class="${status==='New'?'current':'done'}"><i></i>Accepted</div><div class="${status==='Ready to pack'?'current':''}"><i></i>Packed</div><div class="${status==='Dispatched'?'done':''}"><i></i>Dispatched</div></div><div class="card"><div class="entity"><span class="product-thumb">M</span><span><b>${id==='ECP-785198'?'Mini crescent bag':'Sculpted crepe dress'}</b><small>SKU ${id==='ECP-785198'?'ME-BG-442':'ME-DR-104-BLK-M'} · Qty 1</small></span></div></div><div class="notice amber" style="margin-top:14px"><strong>Customer privacy protected</strong>Only fulfilment-safe customer fields are visible. All customer communication remains in SFCC.</div><div class="modal-actions">${status==='New'?'<button class="btn dark" data-accept>Accept order</button>':status==='Ready to pack'?'<button class="btn dark" data-dispatch>Print label & dispatch</button>':'<button class="btn">Download documents</button>'}</div>`);const a=$('[data-accept]');if(a)a.onclick=()=>{state.orders[id]='Ready to pack';save(`${id} accepted by Maison Élan`);$('#modal-root').innerHTML='';toast('Order accepted · pick list created');renderPartner()};const d=$('[data-dispatch]');if(d)d.onclick=()=>{state.orders[id]='Dispatched';save(`${id} dispatched with ATI carrier label`);$('#modal-root').innerHTML='';toast('Carrier label printed · order dispatched');renderPartner()}}
function renderPartner(){partnerNavigation();$('#partner-main').innerHTML=partnerViews[partnerPage]();$('[data-partner-nav]',$('#partner-main')).forEach(x=>x.onclick=()=>{partnerPage=x.dataset.partnerNav;renderPartner()});$$('[data-order]').forEach(x=>x.onclick=()=>orderModal(x.dataset.order));const rec=$('[data-reconcile]');if(rec)rec.onclick=()=>{state.inventory.sync='Healthy';save('Inventory reconciliation completed');toast('18 SKU-location records reconciled')};const fix=$$('[data-fix]');fix.forEach(x=>x.onclick=()=>{state.catalog.issues=Math.max(0,state.catalog.issues-1);state.catalog.ready=Math.min(state.catalog.total,state.catalog.ready+1);save('Vendor resolved a catalogue exception');toast('Issue resolved and resubmitted');renderPartner()});const qc=$('[data-qc]');if(qc)qc.onclick=()=>modal(`<span class="eyebrow">Return quality control</span><h2>RTN-10428</h2><p class="muted">Sculpted crepe dress · Received at ATI Returns Hub</p><div class="choice-grid" style="margin-top:20px"><button class="choice selected"><b>Resaleable</b><small>Return to sellable inventory.</small></button><button class="choice"><b>Damaged</b><small>Non-sellable, vendor chargeback.</small></button><button class="choice"><b>Inspection needed</b><small>Escalate to ATI.</small></button></div><div class="modal-actions"><button class="btn dark" data-complete-qc>Complete QC</button></div>`);const complete=$('[data-complete-qc]');if(complete)complete.onclick=()=>{state.returns['RTN-10428']='QC complete';save('RTN-10428 QC passed; refund and restock events emitted');$('#modal-root').innerHTML='';toast('QC completed · refund trigger sent');renderPartner()};const tour=$('[data-tour]');if(tour)tour.onclick=()=>modal(`<span class="eyebrow">Recommended 4-minute walkthrough</span><h2>Partner workspace</h2><div class="list"><div class="list-row"><span class="list-icon">1</span><span><b>Activation readiness</b><p>Show how approval, catalogue, inventory and test order gate launch.</p></span></div><div class="list-row"><span class="list-icon">2</span><span><b>Catalogue & inventory</b><p>Resolve validation issues and review SKU-location buffers.</p></span></div><div class="list-row"><span class="list-icon">3</span><span><b>Order fulfilment</b><p>Accept, pack and dispatch using ATI-branded documentation.</p></span></div><div class="list-row"><span class="list-icon">4</span><span><b>Returns & settlement</b><p>Complete QC and trace deductions to the statement.</p></span></div></div>`);wireCommon($('#partner-main'))}
if(document.body.dataset.app==='partner')renderPartner();

